/// <summary>
/// Extension of class <c>SalesInvoiceController</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceController))]
final class METSalesInvoiceController_Extension
{
}

Method.Source:
protected void outputReport()
{
    next outputReport();
    SysDocuBrandDetails docuBrandDetails;
    METIndustryKeyTable industryKey = METIndustryKeyTable::find(METCustTable::find(custInvoiceJour.InvoiceAccount).IndustryKey);

    select firstonly ReportName, DesignName, METIndustryKey from docuBrandDetails
        where docuBrandDetails.METIndustryKey == industryKey.IndustryKey
            && docuBrandDetails.ReportName == METConstants::METSalesInvoice;

    if(docuBrandDetails)
    {
        str reportname = docuBrandDetails.ReportName;
        str reportdesign = docuBrandDetails.DesignName;
        this.parmReportName(strFmt(METConstants::ReportInfo,reportname,reportdesign));
    }
}
